cd /workspace/project && python3 << 'EOF'
import paramiko
client = paramiko.SSHClient()
client.set_missing_host_key_policy(paramiko.AutoAddPolicy())
client.connect("46.202.154.25", 22, "root", "2N00py123+++")
# Check game.arelorian.de config
stdin, stdout, stderr = client.exec_command("cat /etc/nginx/sites-enabled/game.arelorian.de")
print("Config:", stdout.read().decode())
client.close()
EOF
Config: server {
    listen 80;
    server_name game.arelorian.de;

    root /var/www/2dmmoepg/apps/web/dist;
    index index.html;

    location / {
        try_files $uri $uri/ /index.html;
    }

    location /api {
        proxy_pass http://localhost:4204;
        proxy_http_version 1.1;
        proxy_set_header Upgrade $http_upgrade;
        proxy_set_header Connection 'upgrade';
        proxy_set_header Host $host;
        proxy_cache_bypass $http_upgrade;
    }

    location /webhook {
        proxy_pass http://localhost:5000/webhook/2dmmoepg;
        proxy_set_header Host $host;
        proxy_set_header X-Real-IP $remote_addr;
        proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
        proxy_set_header X-Forwarded-Proto $scheme;
    }
}
